"""Generated by oa_em_openems. Runs one openEMS excitation described by scene.json.

Run it with the openEMS Python interpreter (CSXCAD_INSTALL_PATH must point at the folder with
CSXCAD.dll). Environment: OA_NUM_THREADS (0 = all cores).
"""

import json
import os
import sys
import time

import numpy as np
from CSXCAD import ContinuousStructure
from openEMS import openEMS

HERE = os.path.dirname(os.path.abspath(__file__))


def load_scene():
    with open(os.path.join(HERE, "scene.json"), encoding="utf-8") as fh:
        return json.load(fh)


def vec(values):
    values = [float(v) for v in values]
    return values[0] if values[0] == values[1] == values[2] else values


def build_properties(csx, scene):
    props = {}
    for name, p in scene["properties"].items():
        kind = p["kind"]
        if kind == "material":
            if p.get("debye"):
                # CSXCAD exposes Debye media only through its generic property factory
                poles = p["debye"]["poles"]
                prop = csx._ContinuousStructure__CreateProperty(
                    "DebyeMaterial",
                    name,
                    order=len(poles),
                    epsilon=vec(p["epsilon"]),
                    kappa=vec(p["kappa"]),
                )
                for k, pole in enumerate(poles):
                    delta = vec(pole["eps_delta"])
                    relax = pole["eps_relax"]
                    relax = relax if np.ndim(delta) == 0 else [relax] * 3
                    prop.SetDispersiveMaterialProperty(k, eps_delta=delta, eps_relax=relax)
            else:
                prop = csx.AddMaterial(name, epsilon=vec(p["epsilon"]), kappa=vec(p["kappa"]))
        elif kind == "metal":
            prop = csx.AddMetal(name)
        elif kind == "sheet":
            prop = csx.AddConductingSheet(
                name, conductivity=p["conductivity"], thickness=p["thickness"]
            )
        elif kind == "lumped":
            kw = {k: p[k] for k in ("R", "L", "C") if p.get(k) is not None}
            prop = csx.AddLumpedElement(
                name, ny=p["ny"], caps=True, LEtype=1 if p["series"] else 0, **kw
            )
        else:
            raise ValueError("unknown property kind " + kind)
        props[name] = prop
    return props


def add_primitives(props, scene):
    for pr in scene["primitives"]:
        prop = props[pr["prop"]]
        shape = pr["shape"]
        if shape == "box":
            prop.AddBox(pr["start"], pr["stop"], priority=pr["priority"])
        elif shape == "polygon":
            pts = np.array(pr["points"], dtype=float).T
            prop.AddPolygon(pts, "z", pr["elevation"], priority=pr["priority"])
        elif shape == "linpoly":
            pts = np.array(pr["points"], dtype=float).T
            prop.AddLinPoly(pts, "z", pr["elevation"], pr["length"], priority=pr["priority"])
        elif shape == "cylinder":
            prop.AddCylinder(pr["start"], pr["stop"], pr["radius"], priority=pr["priority"])
        else:
            raise ValueError("unknown primitive " + shape)


def add_ports(fdtd, csx, props, scene):
    excited = scene["excited"]
    ports = []
    for sp in scene["ports"]:
        exc = 1 if sp["nr"] == excited else 0
        if sp["type"] == "lumped":
            port = fdtd.AddLumpedPort(
                sp["nr"], sp["R"], sp["start"], sp["stop"], sp["exc_dir"], excite=exc, priority=20
            )
        elif sp["type"] == "msl":
            port = fdtd.AddMSLPort(
                sp["nr"],
                props[sp["metal"]],
                sp["start"],
                sp["stop"],
                sp["prop_dir"],
                sp["exc_dir"],
                excite=exc,
                FeedShift=sp["feed_shift"],
                MeasPlaneShift=sp["meas_shift"],
                priority=20,
            )
        elif sp["type"] == "stripline":
            port = fdtd.AddStripLinePort(
                sp["nr"],
                props[sp["metal"]],
                sp["start"],
                sp["stop"],
                sp["prop_dir"],
                sp["exc_dir"],
                sp["height"],
                excite=exc,
                FeedShift=sp["feed_shift"],
                MeasPlaneShift=sp["meas_shift"],
                priority=20,
            )
        else:
            raise ValueError("unknown port type " + sp["type"])
        ports.append(port)
    return ports


def main():
    scene = load_scene()
    unit = scene["unit"]
    t0 = time.time()
    fdtd = openEMS(NrTS=scene["max_timesteps"], EndCriteria=scene["end_criteria"])
    fdtd.SetGaussExcite(scene["excitation"]["f0"], scene["excitation"]["fc"])
    fdtd.SetBoundaryCond(scene["boundary"])
    csx = ContinuousStructure()
    fdtd.SetCSX(csx)
    mesh = csx.GetGrid()
    mesh.SetDeltaUnit(unit)
    for axis in "xyz":
        mesh.AddLine(axis, scene["mesh"][axis])
    props = build_properties(csx, scene)
    add_primitives(props, scene)
    ports = add_ports(fdtd, csx, props, scene)

    nf2ff = None
    if scene.get("nf2ff"):
        nf2ff = fdtd.CreateNF2FFBox()

    sim_path = os.path.join(HERE, "sim")
    threads = int(os.environ.get("OA_NUM_THREADS", "0"))
    fdtd.Run(sim_path, cleanup=True, verbose=2, numThreads=threads)
    wall = time.time() - t0

    freqs = np.array(scene["freqs"], dtype=float)
    arrays = {"freqs": freqs, "excited": np.array([scene["excited"]])}
    for sp, port in zip(scene["ports"], ports, strict=True):
        nr = sp["nr"]
        port.CalcPort(sim_path, freqs)
        arrays[f"u{nr}"] = np.asarray(port.uf_tot, dtype=complex)
        arrays[f"i{nr}"] = np.asarray(port.if_tot, dtype=complex)
        arrays[f"z{nr}"] = np.broadcast_to(
            np.asarray(port.Z_ref, dtype=complex), freqs.shape
        ).copy()
        if hasattr(port, "beta"):
            arrays[f"beta{nr}"] = np.asarray(port.beta, dtype=complex)
            shift = (sp["ref_shift"] - port.measplane_shift) * unit
        else:
            arrays[f"beta{nr}"] = np.zeros(freqs.shape, dtype=complex)
            shift = 0.0
        arrays[f"shift{nr}"] = np.array([shift])
    np.savez(os.path.join(HERE, "ports.npz"), **arrays)

    if nf2ff is not None:
        ff = scene["nf2ff"]
        theta = np.arange(0.0, 180.0 + 1e-9, ff["theta_step_deg"])
        phi = np.arange(0.0, 360.0 - 1e-9, ff["phi_step_deg"])
        lo = np.array([mesh.GetLine(a, 0) for a in range(3)]) * unit
        hi = np.array([mesh.GetLine(a, -1) for a in range(3)]) * unit
        res = nf2ff.CalcNF2FF(sim_path, ff["freqs"], theta, phi, center=0.5 * (lo + hi))
        np.savez(
            os.path.join(HERE, "farfield.npz"),
            freqs=np.array(ff["freqs"], dtype=float),
            theta=np.deg2rad(theta),
            phi=np.deg2rad(phi),
            e_theta=np.array(res.E_theta),
            e_phi=np.array(res.E_phi),
            p_rad=np.array(res.Prad),
            dmax=np.array(res.Dmax),
        )

    import openEMS as _oe

    with open(os.path.join(HERE, "run.json"), "w", encoding="utf-8") as fh:
        json.dump(
            {
                "wall_s": wall,
                "openems_version": getattr(_oe, "__version__", None),
                "python": sys.version.split()[0],
                "excited": scene["excited"],
                "n_ports": len(ports),
            },
            fh,
        )


if __name__ == "__main__":
    main()
